import{_ as n,C as e,o as t,c as h,a2 as i,E as l}from"./chunks/framework.BAQ5ZYJQ.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"errand","text":"Your work, in any environment","tagline":"A conda or uv env, a container, another machine over ssh, a Slurm allocation, any stack of them — errand builds and updates each place from what it declares, syncs your files there and back, and runs whatever you would have typed.","actions":[{"theme":"brand","text":"Get started","link":"/guide/start"},{"theme":"alt","text":"Tutorials","link":"/tutorials/"},{"theme":"alt","text":"GitHub","link":"https://github.com/hleclerc/errand"}]},"features":[{"icon":"🧭","title":"Layers, so you never write the ssh-slurm-apptainer script again","details":"An environment is a stack of layers — micromamba, conda, uv, a venv, Nix, Guix, module load, Docker, Podman, Apptainer, ssh, Slurm, a Windows VM — in any combination. Apptainer inside Slurm inside ssh is three lines.","link":"/guide/environments","linkText":"Environments"},{"icon":"🔄","title":"Built, installed and kept current","details":"Each layer says what it needs — a Python version, a requirements.txt, a container recipe. errand builds it the first time, checks it before every run, and brings it up to date when the declaration changed. What already exists is adopted, never rebuilt behind your back.","link":"/guide/upkeep","linkText":"Keeping them current"},{"icon":"📦","title":"Files there and back","details":"Over ssh the project is rsynced before the command runs, and what you name comes back after: --pull a directory, -o an output directory per run, handed to the command as $ERRAND_OUT_DIR.","link":"/guide/remote","linkText":"Running elsewhere"},{"icon":"🧩","title":"Whatever you would have typed","details":"errand run make check, errand run train.py, errand run ./bench. And for a suite — pytest, Catch2, cargo — `path::test` runs its tests one by one, each recorded, marks and all.","link":"/guide/running","linkText":"Running it"},{"icon":"✖️","title":"Several places at once","details":"--env local,cluster is two runs; --fp 32,64 picks environments by tag, and an environment that does not say covers both. The same command, side by side.","link":"/guide/tags","linkText":"Tags"},{"icon":"🔒","title":"The machine to yourself when it matters","details":"A queue per host, outside the process: errand run -x ./bench waits for what is running and holds everything else back; --cpus and --gpus take a share, and a card is assigned, not merely counted.","link":"/guide/machine","linkText":"Sharing the machine"},{"icon":"🛰️","title":"Detach anything","details":"--batch launches the work and gives you the shell back — a detached session locally, a released ssh command, an sbatch on a cluster. errand status and errand watch say how it is going.","link":"/guide/detached","linkText":"Detached runs"},{"icon":"🪶","title":"No dependencies, ever","details":"errand\'s job is to build the environment the work runs in, so it has to run before any environment exists. It writes YAML without pyyaml and draws its screen with the standard library\'s curses.","link":"/guide/installing","linkText":"Installing"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792187838000}'),r={name:"index.md"};function p(k,s,d,o,c,F){const a=e("Term");return t(),h("div",null,[s[0]||(s[0]=i("",5)),l(a,{scene:"stack",caption:"errand run --env cluster train.py. The ssh, the allocation and the container are the three layers declared above; setting them up, entering them and fetching the files back is errand's part."}),s[1]||(s[1]=i("",8))])}const u=n(r,[["render",p]]);export{y as __pageData,u as default};
